+type Turnstile = {
+  render: (container: HTMLElement, options: Record<string, unknown>) => string;
+  reset: (widgetId: string) => void;
+};
+
+declare global {
+  interface Window {
+    turnstile?: Turnstile;
+  }
+}
+
+type Fields = {
+  givenName: string;
+  familyName: string;
+  contactEmail: string;
+  phone: string;
+  connection: string;
+};
+
+type Errors = SignupErrors;
+
